import fs from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const source = await fs.readFile(path.join(root, 'src/source-data.mjs'), 'utf8');
const reading = await fs.readFile(path.join(root, 'src/reading.mjs'), 'utf8');
const app = await fs.readFile(path.join(root, 'src/app.mjs'), 'utf8');

const bundle = [
  '// Generated by node scripts/build_browser.mjs. Keep the source in the .mjs files.',
  '(function () {',
  source.replace(/^export /gm, ''),
  reading.replace(/^import .*;\r?\n/m, '').replace(/^export /gm, ''),
  app.replace(/^import .*;\r?\n/m, ''),
  '})();',
  ''
].join('\n');

await fs.writeFile(path.join(root, 'src/app.bundle.js'), bundle, 'utf8');
